    z_{k+1}   & = \beta_k z_0 + (1-\beta_k) z_k - \alpha \opB z_{k+1/2} ,
\end{aligned}
\tag{SM-EAG\texttt{+}}
\end{align}

\begin{theorem}[Fast rate of \ref{eqn:SM-EAG+}]
\label{thm:sm-EAG}
Let $\opB\colon \reals^d \to \reals^d$ be $\mu$-strongly monotone and $L$-Lipschitz with $0 < \mu \le L$.
Let $z_\star$ be the zero of $\opB$.
For $\alpha \in \big( 0, \frac{\sqrt{L^2 + \mu^2} + \mu}{L^2} \big]$, SM-EAG\texttt{+} exhibits the rate
\begin{align*}
    \|\opB z_k\|^2 \le \frac{\left(\sqrt{1+2\alpha\mu} + 1\right)^2}{\alpha^2 \left( \sum_{j=0}^{k-1} (1+2\alpha\mu)^{\frac{j}{2}} \right)^2} \|z_0 - z_\star\|^2 ,
    \qquad\text{for } k=1,2,\dots.
\end{align*}
\end{theorem}

