\end{align*}

\begin{lemma}
\label{lem:sm-EAG_Lyapunov}
Let $\opB\colon \reals^d \to \reals^d$ be a $\mu$-strongly monotone, $L$-Lipschitz operator ($0 < \mu \le L$), and let
$\{z_k\}_{k=0,1,\dots}$ be the iterates of \ref{eqn:SM-EAG+} with $\beta_k = \frac{1}{\sum_{j=0}^k (1+2\alpha\mu)^j}$.
Then, the quantities
\begin{align*}
    V_k = p_k \|\opB z_k\|^2 + q_k \langle \opB z_k - \mu (z_k - z_0), z_k - z_0 \rangle + \left( \frac{1}{2\alpha} + \mu \right) \|z_0-z_\star\|^2
\end{align*}
with $p_0 = q_0 = 0$ and $q_k = \frac{1}{(1+2\alpha\mu)^{k-1}} \frac{1}{\beta_{k-1}}$, $p_k = \frac{\eta_k \alpha q_k}{2 \beta_k}$ for $k=1,2,\dots$ satisfy $V_k \ge 0$, $V_0 - V_1 \ge \frac{\alpha (1+2\alpha\mu-\alpha^2 L^2)}{2}\|\opB z_0\|^2$, and
\begin{align*}
    V_k - V_{k+1} \ge \frac{\alpha (1 + 2\alpha\mu - \alpha^2 L^2) q_k}{2\beta_k (1-\beta_k)} \|\eta_k \opB z_k - \opB z_{k+1/2}\|^2
\end{align*}
for $k=1,2,\dots$.
