\subsection{Proof of \texorpdfstring{\cref{lem:sm-EAG_Lyapunov}}{Lemma 4.4}}
When $k=0$, we have $z_{1/2} = z_0$, $z_1 = z_0 - \alpha \opB z_0$, $V_0 = \left( \frac{1}{2\alpha} + \mu\right) \|z_0 - z_\star\|^2$, and
\begin{align*}
    V_1 & = \frac{\alpha}{2}\|\opB z_1\|^2 + \langle \opB z_1 - \mu(z_1 - z_0), z_1 - z_0 \rangle + \left(\frac{1}{2\alpha} + \mu\right) \|z_0 - z_\star\|^2 \nonumber \\
    & = \frac{\alpha}{2}\|\opB z_1\|^2 - \alpha \langle \opB z_1, \opB z_0 \rangle - \alpha^2 \mu \|\opB z_0\|^2 + \left(\frac{1}{2\alpha} + \mu\right) \|z_0 - z_\star\|^2 . 
\end{align*}
Because $\opB$ is $L$-Lipschitz,
\begin{align*}
    0 & \le L^2 \|z_1 - z_0\|^2 - \|\opB z_1 - \opB z_0\|^2 = (\alpha^2 L^2 - 1) \|\opB z_0\|^2 + 2\langle \opB z_0, \opB z_1 \rangle - \|\opB z_1\|^2 .
\end{align*}
Therefore,
\begin{align*}
    V_0 - V_1 & = \alpha^2 \mu \|\opB z_0\|^2 + \alpha \langle \opB z_0, \opB z_1 \rangle - \frac{\alpha}{2} \|\opB z_1\|^2 \\
    & = \frac{\alpha}{2} (1+2\alpha\mu -\alpha^2 L^2) \|\opB z_0\|^2 + \frac{\alpha}{2} \left( (\alpha^2 L^2 - 1) \|\opB z_0\|^2 + 2\langle \opB z_0, \opB z_1 \rangle - \|\opB z_1\|^2 \right) \\
    & \ge \frac{\alpha}{2} (1+2\alpha\mu -\alpha^2 L^2) \|\opB z_0\|^2 \\
    & = \frac{\alpha}{2} (1+2\alpha\mu -\alpha^2 L^2) \|\eta_0 \opB z_0 - \opB z_{1/2}\|^2 
\end{align*}
where the last equality holds because $\eta_0 = 0$ and $z_{1/2} = z_0$.

Now suppose $k\ge 1$. For \ref{eqn:SM-EAG+}, we have the identities
\begin{align}
    z_{k+1} - z_0 & = (1-\beta_k) (z_k - z_0) - \alpha \opB z_{k+1/2} \label{eqn:sm_EAG+_zkp1_minus_z0} \\
    z_k - z_{k+1} & = \beta_k (z_k - z_0) + \alpha \opB z_{k+1/2} \label{eqn:SM-EAG+_zk_minus_zkp1} \\
    z_{k+1/2} - z_{k+1} & = \alpha \opB z_{k+1/2} - \eta_k \alpha \opB z_k . \label{eqn:sm_EAG+_zkhalf_minus_zkp1}
\end{align}
Note that $\beta_k = \frac{1}{\sum_{j=0}^{k} (1+2\alpha\mu)^j}$ satisfies
\begin{align*}
    \frac{1}{\beta_{k}} = \sum_{j=0}^{k} (1+2\alpha\mu)^j = 1 + (1+2\alpha\mu) \sum_{j=0}^{k-1} (1+2\alpha\mu)^j = 1 + \frac{1+2\alpha\mu}{\beta_{k-1}} 
\end{align*}
for $k=1,2,\dots$, so $q_k = \frac{1}{(1+2\alpha\mu)^{k-1}} \frac{1}{\beta_{k-1}}$ satisfies the recurrence relation
\begin{align}
    q_{k+1} = \frac{q_k}{\beta_k} \frac{\beta_{k-1}}{(1+2\alpha\mu)} =
    \frac{q_k}{\beta_k} \frac{1}{\frac{1}{\beta_k} - 1} = \frac{q_k}{1-\beta_k}
    \label{eqn:sm-EAG_recurrence_q_k}
\end{align}
for $k=1,2,\dots$.
Additionally, because $\eta_k = \frac{1-\beta_k}{1+2\alpha\mu}$ and $p_k = \frac{\eta_k \alpha q_k}{2\beta_k}$,
\begin{align}
    p_k = \frac{\alpha (1-\beta_k) q_k}{2\beta_k (1+2\alpha\mu)} = \frac{\alpha}{2} \left( \frac{1}{\beta_k} - 1 \right) \frac{q_k}{1 + 2\alpha\mu} = \frac{\alpha}{2} \frac{1}{\beta_{k-1}} q_k = \frac{\alpha}{2} (1+2\alpha\mu)^{k-1} q_k^2 
    \label{eqn:sm-EAG_pkqk}
\end{align}
and
\begin{align}
    p_{k+1} & = \frac{\eta_{k+1}\alpha q_{k+1}}{2\beta_{k+1}} = \frac{\alpha q_{k+1}}{2\beta_{k+1}} \frac{1-\beta_{k+1}}{1+2\alpha\mu} = \frac{\alpha q_k}{2(1-\beta_k)} \frac{1-\beta_{k+1}}{(1+2\alpha\mu)\beta_{k+1}} \nonumber \\
    & = \frac{\alpha q_k}{2(1-\beta_k)} \frac{1}{1+2\alpha\mu} \left( \frac{1}{\beta_{k+1}} - 1 \right) = \frac{\alpha q_k}{2\beta_k (1-\beta_k)} . 
    \label{eqn:sm-EAG_recurrence_p_k}
\end{align}
The identities~\eqref{eqn:sm-EAG_recurrence_q_k} through \eqref{eqn:sm-EAG_recurrence_p_k} will be useful for the subsequent arguments.

Using $\mu$-strong monotonicity of $\opB$ and the identities~\eqref{eqn:sm_EAG+_zkp1_minus_z0}, \eqref{eqn:SM-EAG+_zk_minus_zkp1} and \eqref{eqn:sm-EAG_recurrence_q_k}, we have
\begin{align}
    V_k - V_{k+1} & \ge V_k - V_{k+1} - \frac{q_k}{\beta_k} \langle z_k - z_{k+1}, \opB z_k - \opB z_{k+1} - \mu(z_k - z_{k+1}) \rangle \nonumber \\
