        & \quad + 2\mu\alpha \left( q_k - (1-\beta_k)q_{k+1} \right) \langle \opB z_{k+1/2}, z_k - z_0 \rangle \\
        & \quad + (q_k - (1-\beta_k) q_{k+1}) \langle \opB z_{k+1}, z_k - z_0 \rangle \\
        & \quad + \mu (1-\beta_k) ((1-\beta_k) q_{k+1} - q_k) \|z_k - z_0\|^2 
    \end{aligned} \nonumber \\
    & \begin{aligned}
        & = p_k \|\opB z_k\|^2 - \frac{\alpha q_k}{\beta_k} \langle \opB z_k, \opB z_{k+1/2} \rangle + \frac{\mu \alpha^2 q_k}{\beta_k (1-\beta_k)} \|\opB z_{k+1/2}\|^2 \\
        & \quad + \frac{\alpha q_k}{\beta_k (1-\beta_k)} \langle \opB z_{k+1/2} , \opB z_{k+1} \rangle - p_{k+1} \|\opB z_{k+1}\|^2 .
    \end{aligned} \label{eqn:sm-EAG_Lyapunov_monotone}
\end{align}
Now because $\opB$ is $L$-Lipschitz,
\begin{align}
\label{eqn:sm-EAG_Lyapunov_Lipschitz}
    \|\opB z_{k+1/2} - \opB z_{k+1}\|^2 \le L^2 \|z_{k+1/2} - z_{k+1}\|^2 = L^2 \|\alpha \opB z_{k+1/2} - \eta_k \alpha \opB z_k\|^2 
\end{align}
where we applied the identity~\eqref{eqn:sm_EAG+_zkhalf_minus_zkp1} for the last equality.
Multiplying $p_{k+1}$ to \eqref{eqn:sm-EAG_Lyapunov_Lipschitz} and then subtracting it from \eqref{eqn:sm-EAG_Lyapunov_monotone}, we obtain
\begin{align}
    V_k - V_{k+1} & \ge ( p_k - p_{k+1} \eta_k^2 \alpha^2 L^2) \|\opB z_k\|^2 - \left( \frac{\alpha q_k}{\beta_k} - 2p_{k+1} \eta_k \alpha^2 L^2 \right) \langle \opB z_k, \opB z_{k+1/2} \rangle \nonumber \\
    & \quad + \left( \frac{\mu\alpha^2 q_k}{\beta_k (1-\beta_k)} + p_{k+1}(1-\alpha^2 L^2) \right) \|\opB z_{k+1/2}\|^2 \nonumber \\
    & \quad + \left( \frac{\alpha q_k}{\beta_k (1-\beta_k)} - 2p_{k+1} \right) \langle \opB z_{k+1/2} , \opB z_{k+1} \rangle \nonumber \\
