    & \quad + \left( \frac{\mu\alpha^2 q_k}{\beta_k (1-\beta_k)} + p_{k+1}(1-\alpha^2 L^2) \right) \|\opB z_{k+1/2}\|^2 \nonumber \\
    & \quad + \left( \frac{\alpha q_k}{\beta_k (1-\beta_k)} - 2p_{k+1} \right) \langle \opB z_{k+1/2} , \opB z_{k+1} \rangle \nonumber \\
    & = \frac{\alpha (1 + 2\alpha\mu - \alpha^2 L^2) q_k}{2\beta_k (1-\beta_k)} \|\eta_k \opB z_k - \opB z_{k+1/2}\|^2
    \label{eqn:sm-EAG_summable_term}
\end{align}
where the last equality follows from the identities $\eta_k = \frac{1-\beta_k}{1+2\alpha\mu}$, $p_k = \frac{\eta_k \alpha q_k}{2\beta_k}$ and \eqref{eqn:sm-EAG_recurrence_p_k}.
As $1 + 2\alpha\mu - \alpha^2 L^2 \ge 0$ if $0 < \alpha \le \frac{\sqrt{L^2 + \mu^2} + \mu}{L^2}$, for this range of $\alpha$,
\begin{align*}
    V_k - V_{k+1} & \ge \frac{\alpha (1 + 2\alpha\mu - \alpha^2 L^2)}{2} (1+2\alpha\mu)^k \|\eta_k \opB z_k - \opB z_{k+1/2}\|^2 \ge 0,
\end{align*}
where we used $\frac{q_k}{\beta_k (1-\beta_k)} = \frac{q_{k+1}}{\beta_k} > (1+2\alpha\mu)^k$.
Now it only remains to show that $V_N \ge 0$ holds for any $N \in \mathbb{N}$; if that is the case, then
\begin{align*}
    & \sum_{k=0}^N (1+2\alpha\mu)^k \|\eta_k \opB z_k - \opB z_{k+1/2}\|^2 \le \frac{2}{\alpha (1 + 2\alpha\mu - \alpha^2 L^2)} (V_0 - V_{N+1}) \\
    & \quad \le \frac{2}{\alpha (1 + 2\alpha\mu - \alpha^2 L^2)} \left( \frac{1}{2\alpha} + \mu \right) \|z_0 - z_\star\|^2 = \frac{1+2\alpha\mu}{\alpha^2 (1 + 2\alpha\mu - \alpha^2 L^2)} \|z_0 - z_\star\|^2 ,
\end{align*}
and taking $N\to\infty$, we obtain~\eqref{eqn:sm-EAG_summability}.

Consider the following shifted version of $V_k$:
\begin{align*}
    W_k = V_k - \left(\frac{1}{2\alpha} + \mu\right) \|z_0 - z_\star\|^2 = p_k \|\opB z_k\|^2 + q_k \langle \opB z_k - \mu (z_k - z_0), z_k - z_0 \rangle .
\end{align*}
Because $\opB$ is $\mu$-strongly monotone, if $\lambda \ge 0$ and $\lambda \ne q_k$,
\begin{align}
    W_k & \ge p_k \|\opB z_k\|^2 + q_k \langle \opB z_k - \mu (z_k - z_0), z_k - z_0 \rangle - \lambda \langle \opB z_k - \mu (z_k - z_\star), z_k - z_\star \rangle \nonumber \\
    &
    \begin{aligned}
        & = p_k \|\opB z_k\|^2 + \langle \opB z_k , (q_k - \lambda) z_k - q_k z_0 + \lambda z_\star \rangle \\
        & \quad + \mu(\lambda-q_k) \|z_k\|^2 + 2 \mu \langle z_k, q_k z_0 - \lambda z_\star \rangle - q_k \mu \|z_0\|^2 + \lambda\mu \|z_\star\|^2  
    \end{aligned} \nonumber \\
    &
    \begin{aligned}
        & = p_k \|\opB z_k\|^2 + \langle \opB z_k , (q_k - \lambda) z_k - q_k z_0 + \lambda z_\star \rangle \\
        & \quad + \frac{\mu}{\lambda - q_k} \left\| (\lambda - q_k) z_k + q_k z_0 - \lambda z_\star \right\|^2 - \frac{q_k \lambda \mu}{\lambda - q_k} \|z_0 - z_\star\|^2 .
    \end{aligned} \nonumber \\ 
    &
    \begin{aligned}
        & = \left( p_k - \frac{\lambda - q_k}{4\mu} \right) \|\opB z_k\|^2 + \frac{\mu}{\lambda - q_k} \left\| \frac{\lambda - q_k}{2\mu} \opB z_k - (\lambda - q_k) z_k - q_k z_0 + \lambda z_\star \right\|^2 \\
        & \quad - \frac{q_k \lambda \mu}{\lambda - q_k} \|z_0 - z_\star\|^2 .
    \end{aligned} \nonumber
\end{align}
Adding $\frac{q_k \lambda \mu}{\lambda - q_k} \|z_0 - z_\star\|^2$ to the both sides and taking $\lambda = q_k + 4\mu p_k$, we obtain 
\begin{align*}
    0 & \le W_k + \left( \frac{q_k^2}{4p_k} + \mu q_k \right) \|z_0 - z_\star\|^2 = V_k ,
\end{align*}
where the last equality follows by applying \eqref{eqn:sm-EAG_pkqk} and then plugging in the expression $q_k = \frac{1}{(1+2\alpha\mu)^{k-1}} \frac{1}{\beta_{k-1}} = \frac{1}{(1+2\alpha\mu)^{k-1}} \frac{(1+2\alpha\mu)^k - 1}{2\alpha\mu}$.

When $k=0$, we have $z_{1/2} = z_0$, $z_1 = z_0 - \alpha \opB z_0$, $V_0 = \left( \frac{1}{2\alpha} + \mu\right) \|z_0 - z_\star\|^2$, and
\begin{align*}
    V_1 & = \frac{\alpha}{2}\|\opB z_1\|^2 + \langle \opB z_1 - \mu(z_1 - z_0), z_1 - z_0 \rangle + \left(\frac{1}{2\alpha} + \mu\right) \|z_0 - z_\star\|^2 \nonumber \\
    & = \frac{\alpha}{2}\|\opB z_1\|^2 - \alpha \langle \opB z_1, \opB z_0 \rangle - \alpha^2 \mu \|\opB z_0\|^2 + \left(\frac{1}{2\alpha} + \mu\right) \|z_0 - z_\star\|^2 . 
\end{align*}

Because $\opB$ is $L$-Lipschitz,
\begin{align*}
    0 & \le L^2 \|z_1 - z_0\|^2 - \|\opB z_1 - \opB z_0\|^2 = (\alpha^2 L^2 - 1) \|\opB z_0\|^2 + 2\langle \opB z_0, \opB z_1 \rangle - \|\opB z_1\|^2 .
\end{align*}

Now suppose $k\ge 1$. For \ref{eqn:SM-EAG+}, we have the identities
\begin{align}
    z_{k+1} - z_0 & = (1-\beta_k) (z_k - z_0) - \alpha \opB z_{k+1/2} \label{eqn:sm_EAG+_zkp1_minus_z0} \\
    z_k - z_{k+1} & = \beta_k (z_k - z_0) + \alpha \opB z_{k+1/2} \label{eqn:SM-EAG+_zk_minus_zkp1} \\
    z_{k+1/2} - z_{k+1} & = \alpha \opB z_{k+1/2} - \eta_k \alpha \opB z_k . \label{eqn:sm_EAG+_zkhalf_minus_zkp1}
\end{align}

Note that $\beta_k = \frac{1}{\sum_{j=0}^{k} (1+2\alpha\mu)^j}$ satisfies
\begin{align*}
    \frac{1}{\beta_{k}} = \sum_{j=0}^{k} (1+2\alpha\mu)^j = 1 + (1+2\alpha\mu) \sum_{j=0}^{k-1} (1+2\alpha\mu)^j = 1 + \frac{1+2\alpha\mu}{\beta_{k-1}} 
\end{align*}

for $k=1,2,\dots$, so $q_k = \frac{1}{(1+2\alpha\mu)^{k-1}} \frac{1}{\beta_{k-1}}$ satisfies the recurrence relation
\begin{align}
    q_{k+1} = \frac{q_k}{\beta_k} \frac{\beta_{k-1}}{(1+2\alpha\mu)} =
    \frac{q_k}{\beta_k} \frac{1}{\frac{1}{\beta_k} - 1} = \frac{q_k}{1-\beta_k}
    \label{eqn:sm-EAG_recurrence_q_k}
\end{align}
for $k=1,2,\dots$.

Additionally, because $\eta_k = \frac{1-\beta_k}{1+2\alpha\mu}$ and $p_k = \frac{\eta_k \alpha q_k}{2\beta_k}$,
\begin{align}
    p_k = \frac{\alpha (1-\beta_k) q_k}{2\beta_k (1+2\alpha\mu)} = \frac{\alpha}{2} \left( \frac{1}{\beta_k} - 1 \right) \frac{q_k}{1 + 2\alpha\mu} = \frac{\alpha}{2} \frac{1}{\beta_{k-1}} q_k = \frac{\alpha}{2} (1+2\alpha\mu)^{k-1} q_k^2 
    \label{eqn:sm-EAG_pkqk}
\end{align}

and
\begin{align}
    p_{k+1} & = \frac{\eta_{k+1}\alpha q_{k+1}}{2\beta_{k+1}} = \frac{\alpha q_{k+1}}{2\beta_{k+1}} \frac{1-\beta_{k+1}}{1+2\alpha\mu} = \frac{\alpha q_k}{2(1-\beta_k)} \frac{1-\beta_{k+1}}{(1+2\alpha\mu)\beta_{k+1}} \nonumber \\
    & = \frac{\alpha q_k}{2(1-\beta_k)} \frac{1}{1+2\alpha\mu} \left( \frac{1}{\beta_{k+1}} - 1 \right) = \frac{\alpha q_k}{2\beta_k (1-\beta_k)} . 
    \label{eqn:sm-EAG_recurrence_p_k}
\end{align}
The identities~\eqref{eqn:sm-EAG_recurrence_q_k} through \eqref{eqn:sm-EAG_recurrence_p_k} will be useful for the subsequent arguments.

